// Extract and validate mooncheck data
const body = $input.item.json;

// Generate mooncheck ID
const moonchecId = `mooncheck_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

// Extract transcript (required)
const transcript = body.transcript || body.text || '';

if (!transcript || transcript.trim().length === 0) {
  throw new Error('Transcript is required');
}

// Extract optional metadata
const topicHint = body.topic_hint || body.topic || '';
const category = body.category || 'blog';
const timestamp = new Date().toISOString();

// Format as mooncheck YAML structure
const moonchecData = {
  id: moonchecId,
  timestamp: timestamp,
  transcript: transcript,
  topic_hint: topicHint,
  category: category,
  word_count: transcript.split(/\s+/).length,
  created_via: 'ios_shortcut',
  status: 'captured'
};

// Prepare for Qdrant embedding
const textForEmbedding = `${category} ${topicHint} ${transcript}`.trim();

return {
  mooncheck: moonchecData,
  text_to_embed: textForEmbedding
};

// Extract embedding from local embedding service response
const response = $input.item.json;
const mooncheck = $('Format Mooncheck').item.json.mooncheck;

// Response format: {embedding: [...], dimension: 384, model: '...'}
return {
  mooncheck: mooncheck,
  embedding: response.embedding
};
